  const { res, body } = await create([{ sku: 'apple', qty: 2 }])
  assert.equal(res.status, 201)
  assert.equal(res.headers.get('content-type'), 'application/json')
  assert.equal(typeof body.id, 'string')
  assert.deepEqual(body, { id: body.id, items: [{ sku: 'apple', qty: 2 }], total: 20 })
})

test('POST /orders ids increment sequentially', async () => {
  const a = (await create([{ sku: 'apple', qty: 1 }])).body.id
  const b = (await create([{ sku: 'apple', qty: 1 }])).body.id
  assert.equal(Number(b), Number(a) + 1)
})

test('POST /orders sums multiple items', async () => {
  const { body } = await create([{ sku: 'apple', qty: 1 }, { sku: 'pear', qty: 2 }])
  assert.equal(body.total, 70)
})

test('POST /orders no discount at exactly 100', async () => {
  assert.equal((await create([{ sku: 'apple', qty: 10 }])).body.total, 100)
})

test('POST /orders 10% discount above 100', async () => {
  assert.equal((await create([{ sku: 'apple', qty: 11 }])).body.total, 99)
})

test('POST /orders total is floored, not rounded', async () => {
  // 33.5*3=100.5 -> 90.45 -> 90 ; 150*1 -> 135
  assert.equal((await create([{ sku: 'odd', qty: 3 }])).body.total, 90)
  assert.equal((await create([{ sku: 'gold', qty: 1 }])).body.total, 135)
})

test('POST /orders qty as numeric string is coerced', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — no input validation; "2" is coerced and echoed as a string
  const { res, body } = await create([{ sku: 'apple', qty: '2' }])
  assert.equal(res.status, 201)
  assert.equal(body.total, 20)
  assert.deepEqual(body.items, [{ sku: 'apple', qty: '2' }])
})

test('POST /orders unknown sku yields total null', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — pricing returns undefined, NaN total serialises as null, still 201
  const { res, body } = await create([{ sku: 'nope', qty: 1 }])
  assert.equal(res.status, 201)
  assert.equal(body.total, null)
})

test('POST /orders 400 for missing items, empty items, non-array items, invalid JSON', async () => {
  for (const [body, raw] of [[{}], [{ items: [] }], [{ items: 'x' }], [null, '{not json']]) {
    const res = await post(body, raw)
    assert.equal(res.status, 400)
    assert.equal(res.headers.get('content-type'), 'application/json')
    assert.deepEqual(await res.json(), { error: 'items required' })
  }
})

test('POST /orders empty body is 400', async () => {
  const res = await fetch(`${base}/orders`, { method: 'POST' })
  assert.equal(res.status, 400)
  assert.deepEqual(await res.json(), { error: 'items required' })
})

test('GET /orders/:id 200 returns stored order', async () => {
  const { body: created } = await create([{ sku: 'pear', qty: 1 }])
  const res = await fetch(`${base}/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.equal(res.headers.get('content-type'), 'application/json')
  assert.deepEqual(await res.json(), created)
})

test('GET /orders/:id unknown id is 200 with error body', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — missing order returns 200, not 404
  const res = await fetch(`${base}/orders/999999`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('unknown routes and methods are 404 {error:"no route"}', async () => {
  for (const [method, path] of [['GET', '/nope'], ['GET', '/orders'], ['POST', '/orders/1'], ['DELETE', '/orders/1'], ['GET', '/orders/1/x']]) {
    const res = await fetch(`${base}${path}`, { method })
    assert.equal(res.status, 404, `${method} ${path}`)
    assert.deepEqual(await res.json(), { error: 'no route' })
  }
})
EOF
